INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64451819', 64451819, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'DINAS TENAGA KERJA, TRANSMIGRASI, DAN ENERGI', 'Penyediaan Jasa Tenaga Ahli Penyusunan Rencana Kerja (Renja) dan Pelaporan Kinerja', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 132000000, 'January 2026', 'APBD', 1, 1, '1 Paket', '1. Melakukan pendampingan dan dokumentasi rapat teknis yang dilaksanakan oleh Sekretariat Dinas Tenaga Kerja, Transmigrasi dan Energi Provinsi DKI Jakarta; 2. Membantu identifikasi isu dan kendala pada pelaksanaan kegiatan Sekretariat Dinas Tenaga Kerja, Transmigrasi dan Energi Provinsi DKI Jakarta terkait pembangunan daerah sektor Ketenagakerjaan, Transmigrasi, dan Energi; 3. Memberikan saran dan pertimbangan terhadap suatu gagasan dan konsep sesuai ruang lingkupnya; 4. Membantu Sekretariat Dinas Tenaga Kerja, Transmigrasi dan Energi Provinsi DKI Jakarta dalam menyusun rencana kerja dan pelaporan kinerja; 5. Melakukan konsultasi, koordinasi dan pertemuan/diskusi internal dengan Perangkat Daerah/Kementerian/Lembaga/Institusi sesuai kebutuhan pengumpulan bahan materi; 6. Melaksanakan dan menyelesaikan pekerjaan sesuai dengan jadwal pelaksanaan pekerjaan yang telah ditetapkan; 7. Melaporkan dan mempresentasikan data dan informasi terkait issue/permasalahan kepada Sekretariat Dinas Tenaga Kerja, Transmigrasi dan Energi Provinsi DKI Jakarta secara periodik; 8. Menghadiri dan melaporkan hasil kegiatan; 9. Membantu penyusunan rencana dan konsep implementasi dalam bentuk rekomendasi program atau kegiatan; dan 10. Tugas tambahan lainnya yang disesuaikan dengan kebutuhan Sekretariat Dinas Tenaga Kerja, Transmigrasi dan Energi Provinsi DKI Jakarta.', '1. Berlatar belakang pendidikan minimal sarjana (S1) pada jurusan/ program studi Ekonomi (Ekonomi Pembangunan/ Ekonomi Regional dan Perkotaan/ Ekonomi Publik); atau 2. Berlatar belakang pendidikan minimal sarjana (S1) pada jurusan/ program studi Statistik (Statistika Bisnis/Industri {Aktuaria/Ekonomi}); atau 3. Berlatar belakang pendidikan minimal sarjana (S1) pada jurusan/ program studi Planologi (Ekonomi dan Sosial Spasial) 4. Memiliki pengalaman bekerja minimal 4 (empat) tahun di Instansi Pemerintah Daerah, Pemerintah Pusat, Lembaga Negara atau instansi/perusahaan lainnya. 5. Memiliki pengalaman bekerja di Instansi Pemerintah Daerah, Pemerintah Pusat, dan Lembaga Negara atau setara; 6. Diutamakan memiliki pengalaman dalam penyusunan dokumen perencanaan pembangunan dan pelaporan kinerja urusan ketenagakerjaan dan energi; 7. Memiliki peralatan kerja sendiri yang diperlukan untuk menjalankan tugas (antara lain seperti laptop, gawai dll); 8. Memiliki kemampuan interpersonal yang kuat dan mampu bekerja secara efektif dalam tim; 9. Mampu bekerja secara efektif di bawah tekanan dan memenuhi tenggat waktu yang ketat; dan 10. Memiliki kemampuan yang baik dalam menggunakan aplikasi Microsoft Office (Word, Excel, Powerpoint). Kemampuan dalam menggunakan aplikasi lainnya yang akan menunjang pekerjaan, lebih diutamakan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1540959);
