INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64473924', 64473924, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT DATA DAN INFORMASI PERENCANAAN PEMBANGUNAN', 'Penyediaan Jasa Konsultansi Perorangan Content Creator 3', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 67375000, 'July 2026', 'APBD', 1, 1, '1 Paket', '" 1.⁠ ⁠Membuat Strategi Komunikasi konten Bappeda setiap triwulan (3 bulan), koordinasi approval hingga input semua STRAKOM pada website komunikasi.jakarta.go.id. 2.⁠ ⁠⁠Membuat Strategi Komunikasi dari event Bappeda (pra-event-post) seperti, Strakom JFF, JID, hingga kebijakan/program yang menjadi prioritas Gubernur seperti, Digitalisasi Pasar. 3.⁠ ⁠⁠Membuat konsep konten media Bappeda dengan menyesuaikan trend konten yang ada atau sesuai arahan pimpinan terkait program yang perlu dibuatkan konsep konten, baik dalam bentuk infografis, reels, dan video 4.⁠ ⁠⁠Mengolah bahan/materi publikasi data dan informasi melalui pembuatan brief infografis, reels, dan video. 5.⁠ ⁠⁠Melakukan pembagian tim konten, desain grafis, video editor dan campers sesuai dengan load kerja yang ada. 6.⁠ ⁠⁠⁠Mengumpulkan ide, data, serta melakukan riset dan membuat konsep untuk menghasilkan suatu konten yang menarik. Sebagai contoh, pimpinan memberikan paparan terkait suatu program/kebijakan, lalu saya perlu membuatnya menjadi konten media yang lebih mudah dipahami untuk dipublikasi di media sosial. 7.⁠ ⁠⁠Melaksanakan arahan/instruksi pimpinan, termasuk request konten dan peliputan baik dari pimpinan Pusdatin, pimpinan bidang/staf bidang, skpd lain yang kemudian dikoordinasikan terlebih dahulu ke pimpinan Pusdatin dan dilaksanakan bersama tim. 8.⁠ ⁠⁠⁠Membuat laporan Triwulan media publikasi Bappeda setiap 3 bulan sekali untuk ditandatangani pimpinan Pusdatin dan diberikan ke Kepala Bappeda. 9.⁠ ⁠⁠Membuat laporan Strakom media publikasi Bappeda setiap 3 bulan sekali yang kemudian disubmit kepada Diskominfotik Jakarta. 10.⁠ ⁠⁠Melakukan review konten hingga koordinasi konten-konten media Bappeda kepada pimpinan, kemudian mengoordinasikannya kembali kepada anggota tim media. 11.⁠ ⁠⁠Membuat paparan yang berkaitan dengan media publikasi sesuai arahan/permintaan pimpinan, baik untuk keperluan pimpinan/acara/bidang/skpd terkait. 12.⁠ ⁠⁠Membuat caption/deskripsi pada setiap konten yang akan dipublikasi hingga melakukan postingan di semua kanal media sosial Bappeda. 13.⁠ ⁠⁠Membuat laporan bulanan sebagai rekap pekerjaan selama satu bulan."', 'Tenaga Ahli Tidak Ber SKA / SKK , S1 Pengalaman Minimal 7 Tahun (Jasa Konsultansi Perorangan Non Konstruksi)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1541869);
