INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63819286', 63819286, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'SEKRETARIAT UTAMA BMKG', 'Sewa Komunikasi M2M GSM untuk 4 balai besar MKG', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 1940000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '9 Bulan', 'Layanan sewa komunikasi Machine to Machine (M2M) memiliki peran vital dalam mendukung operasional berbagai perangkat komunikasi yang terintegrasi dengan alat observasi cuaca dan seismik di lingkungan BMKG. Melalui sistem ini, seluruh perangkat seperti Automatic Weather Station (AWS), Automatic Rain Gauge (ARG), Automatic Agroclimate Weather Station (AAWS), Automatic Weather Observation Station (AWOS), Seismograph, Accelerograph, dan Intensity Meter AWS Maritim, Warning Receiver System - Next Generation (WRS-NG), ARG Rekayasa, tide gauge, sistem prekursor gempa, sirine gempa bumi, display indoor dan display outdoor cuaca, penakar hujan, soil moisture, Automatic Solar Radiation System (ASRS) serta berbagai perangkat IoT lainnya dapat melakukan pengiriman data secara otomatis, real-time, dan berkesinambungan ke pusat data BMKG tanpa memerlukan interaksi manual yang belum tertampung di kegiatan m2m sebelumnya.', 'Menggunakan sistem bulking/shared system untuk seluruh nomor yang terdaftar, sehingga pemakaian kuota data dapat dikelola secara kolektif dan efisien tanpa kehilangan sisa kuota yang tidak terpakai.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1543737);
