INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64418500', 64418500, 'analyze_legacy', 'Kementerian Hukum', 'central', '03 BALAI HARTA PENINGGALAN SEMARANG', 'Pengadaan Layanan Sarana Internal Pengadaan Kendaraan Bermotor Motor listrik  ( roda 2 ) Balai Harta Peninggalan Semarang Tahun Anggaran 2026', 'Barang', 'E-Purchasing', 'Jawa Tengah, Semarang (Kota)', 29120000, 'January 2026', 'APBN - PNBP (D)', 0, 1, '1 unit', 'Uraian Pekerjaan Pengadaan ini merupakan penyediaan kendaraan bermotor roda dua berbasis listrik sebagai kendaraan dinas operasional Balai Harta Peninggalan Semarang, yang dilaksanakan dengan berpedoman pada Standar Barang dan Standar Kebutuhan (SBSK) Kementerian Keuangan serta ketentuan peraturan perundang-undangan yang berlaku. Pengadaan kendaraan bermotor listrik ini dimaksudkan untuk: 1. Memenuhi kebutuhan sarana transportasi operasional kedinasan sesuai SBSK; 2. Mendukung kelancaran pelaksanaan tugas dan fungsi Balai Harta Peninggalan Semarang; 3. Mendukung kebijakan pemerintah dalam penggunaan kendaraan ramah lingkungan dan efisiensi energi. Ruang lingkup pekerjaan meliputi: 1. Pengadaan dan penyerahan kendaraan bermotor roda dua listrik sesuai spesifikasi minimum SBSK; 2. Kendaraan dalam kondisi baru dan siap pakai; 3. Kelengkapan administrasi dan legalitas kendaraan; 4. Pemberian garansi dan layanan purna jual; 5. Pengiriman kendaraan ke lokasi Balai Harta Peninggalan Semarang.', 'Pengadaan Sepeda Motor Listrik sebagai kendaraan dinas operasional dengan ketentuan: motor listrik daya maksimal 5 kW, kondisi baru, tahun produksi tahun berjalan atau paling lama 1 (satu) tahun sebelumnya, dilengkapi baterai dan charger standar pabrikan, jarak tempuh minimal ±50 km per pengisian, sistem pengereman dan penerangan sesuai standar keselamatan, serta legalitas lengkap (STNK dan BPKB). Produk wajib memenuhi Standar Barang dan Standar Kebutuhan (SBSK) sesuai PMK Nomor 138 Tahun 2024 serta ketentuan TKDN/P3DN dengan dibuktikan Sertifikat TKDN yang masih berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1545056);
