INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64419410', 64419410, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'SEKRETARIAT UTAMA BMKG', 'Suku Cadang Sistem Tanda Waktu', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 407436000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Set', 'Pada saat ini terdapat jaringan Tanda Waktu di seluruh dunia yang merupakan acuan standar waktu di dunia. BMKG adalah institusi yang salah satu tupoksinya adalah menginformasikan waktu standar, maka perlu dilakukan pemeliharaan Tanda Waktu di BMKG agar jaringan Tanda Waktu standar tersebut dapat menjadi acuan nasional. Selain itu, agar sistem tanda waktu standar ini dapat beroperasi dengan baik, maka pemeliharaan yang dilakukan adalah yang bersifat korektif maupun preventif. Tujuan dari pemeliharaan sistem tanda waktu adalah untuk mencegah terjadinya kerusakan dan/atau mempertahankan keberlangsungan operasional sistem Tanda Waktu secara terus menerus dan penyediaan barang suku cadang yang siap untuk mengganti peralatan apabila rusak. Sasaran kegiatan Pemeliharaan Sistem Tanda Waktu adalah melakukan pemeliharaan peralatan dan persediaan peralatan Sistem Tanda Waktu pada Pusat Seismologi Teknik Geofisika Potensial dan Tanda Waktu Output dari Pemeliharaan Peralatan Sistem Tanda Waktu adalah terpeliharanya Sistem Tanda Waktu BMKG. Outcome yaitu Sistem tanda waktu BMKG dapat beroperasional dengan baik sehingga layanan Informasi Tanda Waktu kepada masyarakat menjadi tepat dan akurat.', 'Pengadaan barang persediaan (suku cadang) adalah kegiatan pengadaan peralatan system tanda waktu yang dibutuhkan untuk menunjang kegiatan pemeliharaan sistem tanda waktu. Adapun suku cadang yang dimaksud adalah: ● NTP Tanda Waktu ● Audio Interface ● Komputer monitoring ● Monitor Display ● Standing AC 3 Pk ● AC Split ● Antenna GPS ● CCTV ● Pengukur Suhu dan Kelembapan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1547268);
