INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64419268', 64419268, 'analyze_legacy', 'Provinsi Jawa Barat', 'provinsi', 'Dinas Sumber Daya Air', 'Penyusunan Masterplan Drainase Utama Kota Sukabumi', 'Jasa Konsultansi', 'Seleksi', 'Jawa Barat, Bandung (Kota)', 750000000, 'February 2026', 'APBD', 1, 1, '1 Pekerjaan', 'Pekerjaan ini mencakup kegiatan penyusunan dokumen masterplan drainase utama Kota Sukabumi yang bertujuan untuk merumuskan strategi pengelolaan sistem drainase secara menyeluruh dan berkelanjutan. Ruang lingkup pekerjaan meliputi survei dan pemetaan kondisi eksisting jaringan drainase, analisis kapasitas hidraulik, identifikasi titik rawan banjir, penyusunan rekomendasi teknis perbaikan dan pengembangan jaringan, serta penyusunan dokumen perencanaan lengkap sesuai dengan kaidah teknis dan regulasi yang berlaku. Keluaran akhir berupa dokumen masterplan yang dapat dijadikan acuan dalam pelaksanaan pembangunan dan rehabilitasi sistem drainase di wilayah Kota Sukabumi.', 'Pekerjaan ini mencakup kegiatan penyusunan dokumen masterplan drainase utama Kota Sukabumi yang bertujuan untuk merumuskan strategi pengelolaan sistem drainase secara menyeluruh dan berkelanjutan. Ruang lingkup pekerjaan meliputi survei dan pemetaan kondisi eksisting jaringan drainase, analisis kapasitas hidraulik, identifikasi titik rawan banjir, penyusunan rekomendasi teknis perbaikan dan pengembangan jaringan, serta penyusunan dokumen perencanaan lengkap sesuai dengan kaidah teknis dan regulasi yang berlaku. Keluaran akhir berupa dokumen masterplan yang dapat dijadikan acuan dalam pelaksanaan pembangunan dan rehabilitasi sistem drainase di wilayah Kota Sukabumi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1547483);
